const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const titles=(input.sheets||[]).map(s=>String((s.properties||{}).title||'').trim());
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const tabs=[];
for(let k=-1;k<2;k++){const d=new Date(nowIL.getFullYear(),nowIL.getMonth()+k,1); const t=MONTHS[d.getMonth()]+' '+d.getFullYear(); if(d>=new Date(2026,9,1) && titles.includes(t)) tabs.push(t);}
return {body: JSON.stringify({dataFilters: tabs.map(t=>({a1Range:"'"+t+"'!A1:T2000"})).concat([{a1Range:"'בקשות להקדמה'!A1:P5000"}]), valueRenderOption:'FORMATTED_VALUE'})};

const DRY = false;
const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const today=new Date(nowIL.getFullYear(),nowIL.getMonth(),nowIL.getDate());
function parseHeb(s){
  s=String(s||'');
  const m=s.match(/(\d{1,2})\s+(\S+)\s+(\d{4})/);
  if(m){const mi=MONTHS.indexOf(m[2]); if(mi>=0) return new Date(+m[3],mi,+m[1]);}
  const n=s.match(/(\d{1,2})[\/.](\d{1,2})[\/.](\d{2,4})/);
  if(n){let y=+n[3]; if(y<100)y+=2000; return new Date(y,+n[2]-1,+n[1]);}
  return null;
}
function workdaysBetween(a,b){ // Sun-Thu days after a through b inclusive
  let c=0; const x=new Date(a);
  while(true){x.setDate(x.getDate()+1); if(x>b) break; const w=x.getDay(); if(w<=4) c++; if(c>90) break;}
  return c;
}
const digits=v=>String(v||'').replace(/\D/g,'').replace(/^972/,'0');
const all=input.ranges||[];
const isReq=vr=>String((vr.valueRange||{}).range||'').includes('בקשות להקדמה');
const reqVr=all.find(isReq);
const req=(reqVr&&reqVr.valueRange&&reqVr.valueRange.values)||[];
// index sales report rows by customer number and phone
// RULE (15/11/2026, כפילויות): אותו לקוח בכמה שורות/טאבים (אותו נייד 9 ספרות אחרונות או אותו מספר לקוח) = לקוח אחד: דילוג אם אחת השורות בוטלה/בזק/תשתיות, ותאריך+שעת התקנה מהשורה הטובה (טאב החודש, מספר לקוח, תאריך); ביטול/סימון בטאב ישן יותר מהשורה הנבחרת לא חוסם (רכישה חוזרת). Do not remove.
const __ddMo=s=>{const m=String(s==null?'':s).replace(/'/g,'').match(/(\S+)\s+(\d{4})/); if(!m) return undefined; const i=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'].indexOf(m[1]); return i<0?undefined:(+m[2])*12+i;};
const __ddMerge=(L,LOCAL)=>{const P=L.map((_,i)=>i),F=i=>P[i]===i?i:(P[i]=F(P[i])),K={},S=x=>String(x==null?'':x).trim(),E=x=>S(x)==='';
 L.forEach((e,i)=>{e.ph=S(e.ph).replace(/\D/g,''); e.cn=S(e.cn).replace(/\D/g,''); if(e.cn.length<4) e.cn=''; if(e.cand===undefined) e.cand=true;
  e.v={}; for(const f in e.ix) if(e.ix[f]>=0) e.v[f]=e.r[e.ix[f]];
  for(const k of [e.ph.length>=9?'p'+e.ph.slice(-9):'', e.cn?'c'+e.cn:'']){ if(!k) continue; if(K[k]===undefined) K[k]=i; else P[F(i)]=F(K[k]); } });
 const G={}; L.forEach((e,i)=>{(G[F(i)]=G[F(i)]||[]).push(e);}); const M=new Map();
 for(const g of Object.values(G)){ if(g.length<2) continue; g.forEach(e=>M.set(e.r,null));
  const sc=e=>(e.cur?4:0)+(e.cn?2:0)+(e.dt?1:0); const o=g.slice().sort((a,b)=>sc(b)-sc(a)); const b=o.find(e=>e.cand); if(!b) continue;
  const v=Object.assign({},b.v);
  if(E(v.date)){ const d=o.find(e=>e.dt); if(d){ v.date=d.v.date; if(!E(d.v.slot)) v.slot=d.v.slot; } }
  else if(E(v.slot)){ const s=o.find(e=>!E(e.v.slot)&&S(e.v.date)===S(b.v.date)); if(s) v.slot=s.v.slot; }
  for(const f in v){ if(f!=='date'&&f!=='slot'&&E(v[f])){ const s=o.find(e=>!E(e.v[f])); if(s) v[f]=s.v[f]; } }
  const r=b.r.slice(); for(const f in b.ix) if(b.ix[f]>=0&&v[f]!==undefined) r[b.ix[f]]=v[f];
  const x={r,v,b,n:g.length}; g.forEach(e=>{ const old=e.mo!==undefined&&b.mo!==undefined&&e.mo<b.mo; for(const k in (e.fl||{})) if(e.fl[k]&&!(old&&(LOCAL||[]).includes(k))) x[k]=true; e.x=x; }); M.set(b.r,x); }
 return M;};
const __L=[], __cur=MONTHS[today.getMonth()]+' '+today.getFullYear();
const byCust={}, byPhone={};
for(const vr of all.filter(v=>!isReq(v))){
  const vals=(vr.valueRange&&vr.valueRange.values)||[];
  if(!vals.length) continue;
  const h=vals[0].map(x=>String(x||'').trim());
  const ix=name=>h.findIndex(x=>x.startsWith(name));
  const iInst=ix('תאריך התקנה'), iCust=ix('מספר לקוח'), iPhone=ix('נייד'), iNote=ix('הערות'), iWhat=ix('מה נמכר'), iInfra=ix('תשתיות'), iTime=ix('שעת התקנה');
  for(const r of vals.slice(1)){
    const rec={inst:r[iInst], time:iTime>=0?r[iTime]:'', note:String(iNote>=0?(r[iNote]||''):''), what:String(iWhat>=0?(r[iWhat]||''):''), infra:iInfra>=0?String(r[iInfra]||'').trim():''};
    const hasDate=!!parseHeb(rec.inst);
    const c=String(r[iCust]||'').trim(); if(c && (hasDate || !byCust[c])) byCust[c]=rec;
    const p=digits(r[iPhone]); if(p && (hasDate || !byPhone[p])) byPhone[p]=rec;
    if(c||p) __L.push({r, rec, c, p, ix:{date:iInst, slot:iTime}, ph:p, cn:c, cur:String((vr.valueRange||{}).range||'').includes(__cur), mo:__ddMo((vr.valueRange||{}).range), dt:hasDate,
      fl:{bad:rec.note.includes('בוטל')||rec.what.includes('בזק')||rec.infra==='כן'||rec.note.includes('תשתיות')}});
  }
}
const __M=__ddMerge(__L,['bad']);
for(const e of __L){ const x=e.x; if(!x) continue;
  if(!x.rec) x.rec=Object.assign({}, x.b.rec, {inst:x.v.date, time:x.v.slot===undefined?x.b.rec.time:x.v.slot, __bad:!!x.bad});
  if(e.c) byCust[e.c]=x.rec; if(e.p) byPhone[e.p]=x.rec; }
const items=[], data=[], skipped={answered:0,notSentYet:0,already:0,noId:0,tooSoon:0,notInReport:0,dateChanged:0,cancelled:0,closeToInstall:0};
const todayTxt=today.getDate()+'/'+(today.getMonth()+1)+'/'+today.getFullYear();
for(let i=1;i<req.length;i++){
  const r=req[i];
  if(String(r[6]||'').trim()!=='כן'){skipped.notSentYet++; continue;}
  if(String(r[7]||'').trim()||String(r[8]||'').trim()){skipped.answered++; continue;}
  if(String(r[15]||'').trim()){skipped.already++; continue;}
  const sub=String(r[14]||'').trim(); if(!sub){skipped.noId++; continue;}
  const added=parseHeb(r[13]); if(!added||workdaysBetween(added,today)<2){skipped.tooSoon++; continue;}
  const rec=byCust[String(r[9]||'').trim()]||byPhone[digits(r[2])];
  if(!rec){skipped.notInReport++; continue;}
  if(rec.__bad||rec.note.includes('בוטל')||rec.what.includes('בזק')||rec.infra==='כן'||rec.note.includes('תשתיות')){skipped.cancelled++; continue;}
  const inst=parseHeb(rec.inst), reqInst=parseHeb(r[3]);
  if(!inst||!reqInst||inst<reqInst){skipped.dateChanged++; continue;}
  if(workdaysBetween(today,inst)<3){skipped.closeToInstall++; continue;}
  items.push({row:i+1, name:String(r[1]||''), sub:sub, date:String(rec.inst||'').trim()+','+String(rec.time||'').trim(), rep:String(r[5]||'').trim().split(' ')[0]});
  data.push({range:"'בקשות להקדמה'!P"+(i+1), values:[[todayTxt]]});
}
const dbg=JSON.stringify({valueInputOption:'RAW',data:[{range:"'בקשות להקדמה'!P1000",values:[[items.length+' ### '+items.map(x=>x.row+' '+x.name+' '+x.date+' '+x.rep).join(' | ')+' ### '+JSON.stringify(skipped)]]}]});
return {dbg:dbg, count:DRY?0:items.length, found:items.length, names:items.map(x=>x.row+' '+x.name).join(' | '), skipped:JSON.stringify(skipped), items:DRY?[]:items, body:JSON.stringify({valueInputOption:'RAW',data:data})};
